         assign FETCH_Instr_BranchState_n1 = !FETCH_Instr_branch_or_reset_a0 ? FETCH_Instr_BranchState_a0[1:0] : w_FETCH_Instr_BranchState_n1;
         // Staging of $BranchState.
         always @(posedge clk) if (FETCH_Instr_branch_or_reset_a0) FETCH_Instr_BranchState_a0[1:0] <= FETCH_Instr_BranchState_n1[1:0];
         always @(posedge clk) if (FETCH_Instr_branch_or_reset_a1) FETCH_Instr_BranchState_a1[1] <= FETCH_Instr_BranchState_a0[1];

         // Staging of $GoodPathMask.
