         always @(posedge clk) if (FETCH_Instr_valid_decode_a0) FETCH_Instr_divtype_instr_a1 <= FETCH_Instr_divtype_instr_a0;
         always @(posedge clk) if (FETCH_Instr_valid_decode_a1) FETCH_Instr_divtype_instr_a2 <= FETCH_Instr_divtype_instr_a1;

