         // Staging of $pc_inc.
         always @(posedge clk) FETCH_Instr_pc_inc_a1[31:0] <= FETCH_Instr_pc_inc_a0[31:0];

         // Staging of $replay.
         always @(posedge clk) FETCH_Instr_replay_a1 <= FETCH_Instr_replay_a0;

         // Staging of $reset.
         always @(posedge clk) FETCH_Instr_reset_a0 <= FETCH_Instr_reset_n1;

         // Staging of $second_issue.
         always @(posedge clk) FETCH_Instr_second_issue_a1 <= FETCH_Instr_second_issue_a0;

         // Staging of $second_issue_div_ready.
         always @(posedge clk) FETCH_Instr_second_issue_div_ready_a1 <= FETCH_Instr_second_issue_div_ready_a0;

